-------------------------
---- TINTY / COLORS ----
-------------------------

-- Generated by tinty; skel ships a static base16-onedark default.
local colors = require("colors")

-- Hyprland color fields want "rgb(RRGGBB)", not "#RRGGBB".
local function rgb(hex)
	return "rgb(" .. hex:sub(2) .. ")"
end
local function rgba(hex, alpha)
	return "rgba(" .. hex:sub(2) .. alpha .. ")"
end

------------------
---- MONITORS ----
------------------

-- Generic fallback: matches any monitor not covered by a machine-specific rule below.
hl.monitor({
	output = "",
	mode = "preferred",
	position = "auto",
	scale = "auto",
})

-- Machine-specific monitor layout and workspace pinning; optional.
pcall(dofile, os.getenv("HOME") .. "/.config/hypr/local.lua")

-- Deployed only when an NVIDIA GPU was detected at install.
pcall(dofile, os.getenv("HOME") .. "/.config/hypr/nvidia.lua")

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
	hl.exec_cmd("systemctl --user start hyprpolkitagent")
	hl.exec_cmd("waybar & mako & hypridle & hyprpaper & udiskie")
	hl.exec_cmd("fcitx5")
	hl.exec_cmd("xdg-user-dirs-update")
	-- No-op unless this boot is a Limine snapshot entry; see the script.
	hl.exec_cmd("$HOME/.config/hypr/scripts/snapshot-boot-check.sh")
-- `tinty list` is empty until `tinty install` has fetched the schemes and
-- templates, so run it (and build the local templates) on first login and
-- retry on later logins if it failed, e.g. no network yet.
	hl.exec_cmd("command -v tinty >/dev/null 2>&1 && { tinty list | grep -q . || { tinty install && /usr/local/lib/sobarch/build-tinty-templates.sh; }; tinty init; }")
end)

-------------------------------
---- WALLPAPER ON HOTPLUG ----
-------------------------------

-- Recompose the wallpaper when a monitor is plugged or unplugged.
-- pcall so an unknown event name can't abort the rest of this file.
local function refresh_wallpaper()
	hl.exec_cmd("$HOME/.config/hypr/scripts/apply-wallpaper.sh")
end
pcall(function() hl.on("monitor.added", refresh_wallpaper) end)
pcall(function() hl.on("monitor.removed", refresh_wallpaper) end)

hl.exec_cmd('gsettings set org.gnome.desktop.interface gtk-theme "adw-gtk3"')
hl.exec_cmd('gsettings set org.gnome.desktop.interface color-scheme "prefer-dark"')
hl.exec_cmd('gsettings set org.gnome.desktop.interface icon-theme "Papirus-Dark"')

