-- All animations off except layer fade-out. Each fuzzel menu level is its
-- own process, and the fading layer covers the gap before the next one maps.
-- The curve stays near opaque until the end so there is no blank frame.
hl.curve("holdThenFade", { type = "bezier", points = { { 0.7, 0 }, { 1, 0.6 } } })
hl.animation({ leaf = "global", enabled = false })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.2, bezier = "holdThenFade" })

hl.config({
	dwindle = {
		preserve_split = true,
	},
})

hl.config({
	misc = {
		force_default_wallpaper = -1,
		disable_hyprland_logo = true,
		disable_splash_rendering = true,
	},
})

