require("keybinds")

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

hl.window_rule({
	name = "suppress-maximize-events",
	match = { class = ".*" },
	suppress_event = "maximize",
})

hl.window_rule({
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},
	no_focus = true,
})

hl.window_rule({
	name = "float-network-manager",
	match = { title = ".*Network Manager.*" },
	float = true,
})

-- slurp and hyprpicker close right before grim captures the screen, so
-- they must vanish instantly instead of fading into the capture.
hl.layer_rule({
	name = "no-anim-screenshot-overlays",
	match = { namespace = "^(selection|hyprpicker)$" },
	no_anim = true,
})

-- Skip rendering below this alpha so blur doesn't flash the rounded corners.
hl.layer_rule({
	name = "rounded-waybar",
	match = { namespace = "^(waybar)$" },
	blur = true,
	ignore_alpha = 0.5,
})
